// Extract tenant's external labels from hashring configs.
// If one tenant appears in multiple hashring configs,
// only the external label set from the first hashring config is applied.
var err error
lset, err = t.tenantExternalLabels(tenantID, lset)
if err != nil {
	return err
}

func (t *MultiTSDB) tenantExternalLabels(tenantID string, initialLset labels.Labels) (labels.Labels, error) {
	for _, hc := range t.hashringConfigs {
		for _, tenant := range hc.Tenants {
			if tenant == tenantID {
				lset, err := parseAndExtendSortedLabels(initialLset, hc.ExternalLabels, t.logger)
				if err != nil {
					return nil, errors.Wrap(err, "failed to parse external labels for tenant "+tenantID)
				}
				return lset, nil
			}
		}
	}
	return initialLset, nil
}

